gUc(){return"\u0911\u0930\u094d\u0921\u0930 \u0907\u0924\u093f\u0939\u093e\u0938 \u092e\u0947\u0902 \u0935\u093e\u092a\u0938 \u0932\u093e\u092f\u093e \u0917\u092f\u093e\u0964"},
gTC(){return"\u0907\u0924\u093f\u0939\u093e\u0938 \u092e\u0947\u0902 \u0911\u0930\u094d\u0921\u0930 \u0915\u0940 \u0926\u0943\u0936\u094d\u092f\u0924\u093e \u0905\u092a\u0921\u0947\u091f \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u0940\u0964 \u092b\u093f\u0930 \u092a\u094d\u0930\u092f\u093e\u0938 \u0915\u0930\u0947\u0902\u0964"},
