Wf(a,b){return a+" \u0438 \u043e\u043a\u0440\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u0438 ("+b+" \u043a\u043c)"},
We(a,b){return a+" \u0438 \u0441\u043e\u0441\u0435\u0434\u043d\u0438\u0435 \u043d\u0430\u0441\u0435\u043b\u0451\u043d\u043d\u044b\u0435 \u043f\u0443\u043d\u043a\u0442\u044b ("+b+" \u043a\u043c)"},
gBG(){return"\u0424\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043e\u043f\u043b\u0430\u0442\u0430"},
