Gi(a,b,c,d){return"\u0417\u0430\u043b\u0438\u0448\u0438\u043b\u043e\u0441\u044f \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u044c - "+a+": "+b+"; "+c+": "+d+"."},
