gUT(){return"\u0414\u043e\u0434\u0430\u0442\u0438 \u0456\u043d\u043e\u0437\u0435\u043c\u043d\u0443 \u043c\u043e\u0432\u0443"},
gVw(){return"\u0412\u0432\u0435\u0434\u0456\u0442\u044c \u0449\u043e\u043d\u0430\u0439\u043c\u0435\u043d\u0448\u0435 \u0434\u0432\u0430 \u0441\u0438\u043c\u0432\u043e\u043b\u0438 \u043d\u0430\u0437\u0432\u0438 \u0430\u0431\u043e \u043a\u043e\u0434\u0443 \u043c\u043e\u0432\u0438, \u043a\u0440\u0456\u043c \u043f\u0440\u043e\u0431\u0456\u043b\u0456\u0432, \u0449\u043e\u0431 \u043f\u043e\u0431\u0430\u0447\u0438\u0442\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0438."},
